from itertools import product

# Partitions are padded r-tuples.  LR tableau cells are read top row to bottom row,
# and within a row right-to-left.
def partitions_box(r,q):
    out=[]
    def rec(prev, row, cur):
        if row==r:
            out.append(tuple(cur)); return
        for x in range(prev,-1,-1):
            cur.append(x); rec(x,row+1,cur); cur.pop()
    rec(q,0,[])
    return out

def size(p): return sum(p)
def contains(nu,mu): return all(a>=b for a,b in zip(nu,mu))

def lr_coeff(lam, mu, nu):
    # General backtracking LR implementation. Content is lam: lam[t-1] entries t.
    if not contains(nu,mu) or size(nu)-size(mu)!=sum(lam): return 0
    cells=[]
    for rr in range(len(nu)):
        for cc in range(nu[rr],mu[rr],-1): # right-to-left
            cells.append((rr,cc))
    m=len(lam); used=[0]*m; fill={}; ans=0
    def bt(pos):
        nonlocal ans
        if pos==len(cells): ans+=1; return
        rr,cc=cells[pos]
        right=fill.get((rr,cc+1))
        above=fill.get((rr-1,cc))
        for val in range(1,m+1):
            if used[val-1]>=lam[val-1]: continue
            # rows weakly increase left-to-right; columns strictly increase downward.
            if right is not None and val>right: continue
            if above is not None and above>=val: continue
            used[val-1]+=1
            # ballot condition on the right-to-left row word.
            if all(used[t]>=used[t+1] for t in range(m-1)):
                fill[(rr,cc)]=val; bt(pos+1); del fill[(rr,cc)]
            used[val-1]-=1
    bt(0)
    return ans

def horizontal(mu,nu):
    cols=set()
    for rr,(a,b) in enumerate(zip(mu,nu)):
        for cc in range(a+1,b+1):
            if cc in cols: return False
            cols.add(cc)
    return True

def relations_lr(r,q,rho):
    P=partitions_box(r,q)
    U=[p for p in P if contains(p,rho)]
    bydeg={}
    for p in P: bydeg.setdefault(size(p),[]).append(p)
    blocks={}
    for d in range(size(rho),r*q+1):
        V=[p for p in U if size(p)==d]
        if not V: continue
        ix={p:a for a,p in enumerate(V)}; rows=[]
        for k in range(1,q+1):
            for mu in U:
                if size(mu)+k!=d: continue
                row={}
                for nu in bydeg.get(d,[]):
                    if nu in ix:
                        c=lr_coeff((k,),mu,nu)
                        if c: row[ix[nu]]=c
                if row: rows.append(row)
        blocks[d]=(len(V),rows)
    return blocks

def relations_pieri(r,q,rho):
    P=partitions_box(r,q)
    U=[p for p in P if contains(p,rho)]
    bydeg={}
    for p in P: bydeg.setdefault(size(p),[]).append(p)
    blocks={}
    for d in range(size(rho),r*q+1):
        V=[p for p in U if size(p)==d]
        if not V: continue
        ix={p:a for a,p in enumerate(V)}; rows=[]
        for k in range(1,q+1):
            for mu in U:
                if size(mu)+k!=d: continue
                row={}
                for nu in bydeg.get(d,[]):
                    if nu in ix and contains(nu,mu) and horizontal(mu,nu): row[ix[nu]]=1
                if row: rows.append(row)
        blocks[d]=(len(V),rows)
    return blocks

def unit_snf_free(ncols, rows):
    # Integral row operations and deletion of a unit pivot variable/relation.
    # If all residual entries vanish, this is a certificate that the block has
    # SNF diag(1,...,1,0,...,0), hence no torsion.
    rows=[dict(x) for x in rows if x]
    active=set(range(ncols)); piv=0
    while True:
        found=None
        for a,row in enumerate(rows):
            for c,v in row.items():
                if c in active and abs(v)==1:
                    found=(a,c,v); break
            if found: break
        if found is None: break
        a,c,v=found
        pivot=rows[a]
        if v==-1: pivot={x:-z for x,z in pivot.items()}; rows[a]=pivot
        # Clear pivot column from every other relation by integer row operations.
        for b,row in enumerate(rows):
            if b==a: continue
            z=row.get(c,0)
            if z:
                nr=dict(row)
                for x,w in pivot.items():
                    nr[x]=nr.get(x,0)-z*w
                    if nr[x]==0: del nr[x]
                rows[b]=nr
        active.remove(c); piv+=1
        rows.pop(a)
    residual=any(row for row in rows)
    return (not residual, ncols-piv, piv, len(rows))

def family_counts(r,q,i,j):
    a=min(q-i,r-j); b=min(i,j); rho=(i,)*j+(0,)*(r-j)
    P=partitions_box(r,q)
    first=[p for p in P if contains(p,rho) and all(p[x] <= (i+a if x<b else i if x<j else 0) for x in range(r))]
    # (i^j,b^a), interpreted as concatenated parts then padded and sorted;
    # b<=i and a can extend below j.
    top=(i,)*j+(b,)*a
    top=top[:r]+(0,)*max(0,r-len(top))
    second=[p for p in P if contains(p,rho) and contains(top,p)]
    return a,b,len(first),len(second)

# Required regressions.
assert lr_coeff((1,1),(1,),(3,))==0
assert lr_coeff((1,1),(2,),(2,2))==0

cases=[]
for r in range(1,6):
  for q in range(1,7):
    if r<=4 and q<=5: continue
    for i in range(1,q):
      for j in range(1,r): cases.append((r,q,i,j))
assert len(cases)==90

summary=[]
for r,q,i,j in cases:
    rho=(i,)*j+(0,)*(r-j)
    L=relations_lr(r,q,rho)
    P=relations_pieri(r,q,rho)
    assert L==P, (r,q,i,j,'LR/Pieri mismatch')
    free=0; allunit=True
    for d,(ncols,rows) in L.items():
        ok,f,_,_=unit_snf_free(ncols,rows)
        allunit &= ok; free += f
    a,b,n1,n2=family_counts(r,q,i,j)
    N=n1
    assert n1==n2
    assert N>1
    assert allunit and free==N, (r,q,i,j,free,N)
    summary.append((r,q,i,j,N))

from collections import Counter
by_rq=Counter((r,q) for r,q,i,j,N in summary)
by_N=Counter(N for r,q,i,j,N in summary)
print('LR regressions: c_(1,1),(1)^(3)=0; c_(1,1),(2)^(2,2)=0')
print('instances=',len(summary),'all_LR_relation_blocks_equal_Pieri_blocks=True')
print('all 90: unit-SNF reduction gives torsion-free quotient and free rank N; both family cardinalities equal N')
print('cases by (r,q), counted over (i,j):',sorted(by_rq.items()))
print('N distribution:',sorted(by_N.items()))
print('maximum N=',max(N for *_,N in summary))
